                function showOrderLog() {
                    const orderId = document.getElementById('order_id').value.trim();
                    fetch('/get_order_logs/' + orderId)
                        .then(response => response.json())
                        .then(data => {
                            let logsHtml = '';
                            if (data.logs && data.logs.length > 0) {
                                logsHtml += `
Customer Information`;
                                logsHtml += '';
                                logsHtml += '
SenderReceiver';
                                logsHtml += '';
                                logsHtml += `



Sender: ${data.sender.name}

Phone: ${data.sender.phone}

Address: ${data.sender.address}



Receiver: ${data.receiver.name}

Phone: ${data.receiver.phone}

Address: ${data.receiver.address}

                                            `;
                                logsHtml += '';

                                logsHtml += `
Logs Details`;
                                logsHtml += `
Estimated Delivery Date: ${data.estimated_delivery_date}`;
                                data.logs.forEach(log => {
                                    logsHtml += `


Date: ${log.date}

${log.body}

                                                `;
                                });
                            } else {
                                logsHtml = '
No logs found for this order.';
                            }
                            document.getElementById('orderLogContent').innerHTML = logsHtml;
                            document.getElementById('orderLogLabel').innerText = `Order: ${orderId}`;
                            jQuery('#orderLogModal').modal('show');
                        })
                        .catch(error => {
                            console.error('Error fetching order logs:', error);
                        });
                }

div.script:
const map = L.map('map');
console.log(navigator.geolocation);

if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(function(position) {
        const lat = position.coords.latitude;
        const lon = position.coords.longitude;

        map.setView([lat, lon], 13);

        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 19,
        }).addTo(map);

        L.marker([lat, lon]).addTo(map)
            .bindPopup('You are here!')
            .openPopup();
    }, function() {
        alert('Could not get your location.');
        map.setView([51.505, -0.09], 13);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 19,
        }).addTo(map);
    });
} else {
    alert('Geolocation is not supported by this browser.');
    map.setView([51.505, -0.09], 13);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
    }).addTo(map);
};

document.addEventListener('DOMContentLoaded', function () {
    const shippingFeeDisplay = document.getElementById('shipping_fee_display');
    const totalFeeElement = document.getElementById('total_fee');
    const insuranceCheckbox = document.getElementById('insurance');
    const promoCodeInput = document.getElementById('promotion_code');
    const promoDiscountElement = document.getElementById('promotion_discount');
    const insuranceFeeDiv = document.getElementById('insurance_fee');
    let isInsuranceActive = false;
    let isPromoActive = false;

    const observer = new MutationObserver(updateTotalFee);
    observer.observe(shippingFeeDisplay, { childList: true, subtree: true });

    insuranceCheckbox.addEventListener('change', () => {
        isInsuranceActive = insuranceCheckbox.checked;
        insuranceFeeDiv.style.display = isInsuranceActive ? 'flex' : 'none';
        updateTotalFee();
    });

    window.applyPromotion = function () {
        const promoCode = promoCodeInput.value.trim();
        const validPromoCode = 'DHLCODE';

        if (promoCode === validPromoCode) {
            isPromoActive = true;
            promoDiscountElement.style.display = 'flex';
            promoDiscountElement.textContent = '-5,000 VND';
        } else {
            isPromoActive = false;
            promoDiscountElement.style.display = 'none';
            if (promoCode) alert('Invalid promo code');
        }

        updateTotalFee();
    };

    function updateTotalFee() {
        const shippingFeeValue = parseInt(shippingFeeDisplay.textContent.replace(/[^\d]/g, ''), 10) || 0;
        let total = shippingFeeValue;

        if (isInsuranceActive) total += 5000;
        if (isPromoActive) total -= 5000;

        total = Math.max(total, 0);
        totalFeeElement.textContent = total.toLocaleString('en-US') + ' VND';
        document.getElementById('total_fee_input').value = total;
    }

    updateTotalFee();
});

let isExpanded = false;

function toggleLogs() {
    const logs = document.querySelectorAll('.log-entry');
    isExpanded = !isExpanded; // Đảo trạng thái trước

    logs.forEach((log, index) => {
        if (index === 0) {
            log.style.display = 'block';
        } else {
            log.style.display = isExpanded ? 'block' : 'none';
        }
    });

    document.getElementById('viewMoreBtn').textContent = isExpanded ? 'Collapse' : 'View More';
}

document.addEventListener('DOMContentLoaded', () => {
    const logs = document.querySelectorAll('.log-entry');
    logs.forEach((log, index) => {
        log.style.display = index === 0 ? 'block' : 'none';
    });
});
